import sys

sys.setrecursionlimit(1_000_000)

RESERVED = {"fun", "let", "rec", "in", "if", "then", "else", "true", "false"}


class SyntaxError_(Exception):
    pass


class Lexer:
    def __init__(self, s):
        self.s = s
        self.n = len(s)
        self.i = 0

    def tokens(self):
        toks = []
        s, n, i = self.s, self.n, 0
        while i < n:
            c = s[i]
            if c in " \t\n":
                i += 1
                continue

            if "0" <= c <= "9":
                j = i + 1
                while j < n and "0" <= s[j] <= "9":
                    j += 1
                toks.append(("int", int(s[i:j])))
                i = j
                continue

            if (c.isascii() and c.islower()) or c == "_":
                j = i + 1
                while j < n:
                    ch = s[j]
                    if (ch.isascii() and ch.isalpha()) or ch.isdigit() or ch == "_" or ch == "'":
                        j += 1
                    else:
                        break
                name = s[i:j]
                if name in RESERVED:
                    toks.append(("kw", name))
                else:
                    toks.append(("name", name))
                i = j
                continue

            if c == "-" and i + 1 < n and s[i + 1] == ">":
                toks.append(("op", "->"))
                i += 2
                continue

            if c == ":" and i + 1 < n and s[i + 1] == ":":
                toks.append(("op", "::"))
                i += 2
                continue

            if c == "[" and i + 1 < n and s[i + 1] == "]":
                toks.append(("nil", None))
                i += 2
                continue

            if c in "() , + - * = <".split() and len(c) == 1:
                toks.append(("op", c))
                i += 1
                continue

            raise SyntaxError_(SyntaxError)

        return toks


class Parser:
    def __init__(self, toks):
        self.toks = toks
        self.i = 0
        self.n = len(toks)

    def peek(self):
        if self.i >= self.n:
            return ("eof", None)
        return self.toks[self.i]

    def accept_kw(self, kw):
        t = self.peek()
        if t == ("kw", kw):
            self.i += 1
            return True
        return False

    def accept_op(self, op):
        t = self.peek()
        if t == ("op", op):
            self.i += 1
            return True
        return False

    def expect_op(self, op):
        if not self.accept_op(op):
            raise SyntaxError_(SyntaxError)

    def expect_kw(self, kw):
        if not self.accept_kw(kw):
            raise SyntaxError_(SyntaxError)

    def parse_all(self):
        e = self.parse_low()
        if self.i != self.n:
            raise SyntaxError_(SyntaxError)
        return e

    def parse_low(self):
        k = self.peek()[0]
        if k == "kw":
            kw = self.peek()[1]
            if kw == "fun":
                return self.parse_fun()
            if kw == "let":
                return self.parse_let()
            if kw == "if":
                return self.parse_if()
        return self.parse_eq()

    def parse_eq(self):
        node = self.parse_cons()
        while True:
            t = self.peek()
            if t == ("op", "=") or t == ("op", "<"):
                self.i += 1
                node = ("op2", t[1], node, self.parse_cons())
            else:
                break
        return node

    def parse_cons(self):
        node = self.parse_arith()
        if self.accept_op("::"):
            node = ("op2", "::", node, self.parse_cons())
        return node

    def parse_arith(self):
        node = self.parse_mul()
        while True:
            t = self.peek()
            if t == ("op", "+") or t == ("op", "-"):
                self.i += 1
                node = ("op2", t[1], node, self.parse_mul())
            else:
                break
        return node

    def parse_mul(self):
        node = self.parse_app()
        while self.accept_op("*"):
            node = ("op2", "*", node, self.parse_app())
        return node

    def starts_atom(self):
        t = self.peek()
        k = t[0]
        if k == "int" or k == "name" or k == "nil" or k == "lparen":
            return True
        if k == "kw" and t[1] in ("true", "false"):
            return True
        return False

    def parse_app(self):
        node = self.parse_atom()
        while self.starts_atom():
            node = ("app", node, self.parse_atom())
        return node

    def parse_atom(self):
        t = self.peek()
        k = t[0]
        if k == "int":
            self.i += 1
            return ("int",)
        if k == "kw":
            kw = t[1]
            if kw == "true" or kw == "false":
                self.i += 1
                return ("bool",)
            raise SyntaxError_(SyntaxError)
        if k == "name":
            self.i += 1
            return ("var", t[1])
        if k == "nil":
            self.i += 1
            return ("nil",)
        if k == "op" and t[1] == "(":
            self.i += 1
            e1 = self.parse_low()
            if self.accept_op(","):
                e2 = self.parse_low()
                self.expect_op(")")
                return ("pair", e1, e2)
            self.expect_op(")")
            return e1
        raise SyntaxError_(SyntaxError)

    def parse_fun(self):
        self.expect_kw("fun")
        args = []
        while self.peek()[0] == "name":
            args.append(self.peek()[1])
            self.i += 1
        if not args:
            raise SyntaxError_(SyntaxError)
        self.expect_op("->")
        body = self.parse_low()
        return ("fun", args, body)

    def parse_let(self):
        self.expect_kw("let")
        rec = False
        if self.accept_kw("rec"):
            rec = True
        if self.peek()[0] != "name":
            raise SyntaxError_(SyntaxError)
        name = self.peek()[1]
        self.i += 1
        args = []
        while self.peek()[0] == "name":
            args.append(self.peek()[1])
            self.i += 1
        if rec and not args:
            raise SyntaxError_(SyntaxError)
        self.expect_op("=")
        expr = self.parse_low()
        self.expect_kw("in")
        body = self.parse_low()
        if args:
            expr = ("fun", args, expr)
        return ("let", name, expr, body, rec)

    def parse_if(self):
        self.expect_kw("if")
        cond = self.parse_eq()
        self.expect_kw("then")
        then_ = self.parse_low()
        self.expect_kw("else")
        else_ = self.parse_low()
        return ("if", cond, then_, else_)


class Type:
    __slots__ = ("kind", "left", "right", "ref", "id", "level", "parent", "rank", "heap")

    def __init__(self, kind, left=None, right=None, ref=None, id=None, level=0, heap=None):
        self.kind = kind
        self.left = left
        self.right = right
        self.ref = ref
        self.id = id
        self.level = level
        self.parent = self
        self.rank = 0
        self.heap = heap


class HeapNode:
    __slots__ = ("val", "var", "left", "right")

    def __init__(self, val, var):
        self.val = val
        self.var = var
        self.left = None
        self.right = None


def heap_merge(a, b):
    if a is None:
        return b
    if b is None:
        return a
    if a.val < b.val:
        a, b = b, a
    a.left, a.right = heap_merge(a.right, b), a.left
    return a


def find(x):
    r = x
    while r.parent is not r:
        r = r.parent
    while x.parent is not r:
        nx = x.parent
        x.parent = r
        x = nx
    return r


def union_roots(ra, rb):
    if ra is rb:
        return ra
    if ra.rank < rb.rank:
        ra, rb = rb, ra
    rb.parent = ra
    if ra.rank == rb.rank:
        ra.rank += 1
    ra.heap = heap_merge(ra.heap, rb.heap)
    rb.heap = None
    return ra


def union_types(a, b):
    ra = find(a)
    rb = find(b)
    if ra is rb:
        return
    union_roots(ra, rb)


def get_max(root):
    root = find(root)
    h = root.heap
    while h is not None:
        v = h.var
        if v.level == h.val:
            break
        h = heap_merge(h.left, h.right)
    root.heap = h
    return h.val if h is not None else 0


class InferContext:
    def __init__(self):
        self.var_counter = 0
        self.level = [0]

    def fresh(self, level=None):
        if level is None:
            level = self.level[0]
        self.var_counter += 1
        v = Type("var", id=self.var_counter, level=level)
        v.heap = HeapNode(level, v)
        return v


INT = Type("int")
BOOL = Type("bool")


def make_list(t):
    t = Type("list", left=t)
    union_types(t, t.left)
    return t


def make_pair(a, b):
    t = Type("pair", left=a, right=b)
    union_types(t, t.left)
    union_types(t, t.right)
    return t


def make_arrow(a, b):
    t = Type("arrow", left=a, right=b)
    union_types(t, t.left)
    union_types(t, t.right)
    return t


def resolve(t):
    path = []
    cur = t
    while cur.kind == "var" and cur.ref is not None:
        path.append(cur)
        cur = cur.ref
    for v in path:
        v.ref = cur
    return cur


def unify(a, b):
    stack = [(a, b)]
    while stack:
        x, y = stack.pop()
        x = resolve(x)
        y = resolve(y)

        if x is y:
            continue

        kx = x.kind
        ky = y.kind

        if kx == "var" and ky == "var":
            rx = find(x)
            ry = find(y)
            if rx is ry:
                continue
            maxy = get_max(ry)
            if x.level > maxy:
                x.level = maxy
                x.heap = heap_merge(x.heap, HeapNode(maxy, x))
            union_roots(rx, ry)
            continue

        if kx == "var":
            rx = find(x)
            ry = find(y)
            if rx is ry:
                raise TypeError(TypeError)
            maxy = get_max(ry)
            if x.level > maxy:
                x.level = maxy
                x.heap = heap_merge(x.heap, HeapNode(maxy, x))
            x.ref = y
            union_roots(rx, ry)
            continue

        if ky == "var":
            ry = find(y)
            rx = find(x)
            if rx is ry:
                raise TypeError(TypeError)
            maxx = get_max(rx)
            if y.level > maxx:
                y.level = maxx
                y.heap = heap_merge(y.heap, HeapNode(maxx, y))
            y.ref = x
            union_roots(ry, rx)
            continue

        if kx != ky:
            raise TypeError(TypeError)

        if kx == "int" or kx == "bool":
            continue

        if kx == "list":
            stack.append((x.left, y.left))
        elif kx == "pair":
            stack.append((x.left, y.left))
            stack.append((x.right, y.right))
        elif kx == "arrow":
            stack.append((x.left, y.left))
            stack.append((x.right, y.right))


def generalize(t, current_level):
    vars_ = []
    seen_vars = set()
    seen_nodes = set()
    stack = [t]
    while stack:
        node = resolve(stack.pop())
        if node.kind == "var":
            if node.id not in seen_vars:
                seen_vars.add(node.id)
                if node.level > current_level:
                    vars_.append(node)
        else:
            if node in seen_nodes:
                continue
            seen_nodes.add(node)
            if node.kind == "list":
                stack.append(node.left)
            elif node.kind in ("pair", "arrow"):
                stack.append(node.left)
                stack.append(node.right)
    return (vars_, t)


def instantiate(scheme, ctx):
    qvars = scheme[0]
    t = scheme[1]
    if not qvars:
        return t

    mapping = {}
    for v in qvars:
        mapping[v.id] = ctx.fresh()
    qids = set(mapping.keys())

    def copy(t):
        t = resolve(t)
        if t.kind == "var":
            if t.id in qids:
                return mapping[t.id]
            return t

        if t.kind == "int" or t.kind == "bool":
            return t

        if t.kind == "list":
            nt = Type("list")
            union_types(nt, copy(t.left))
            nt.left = t.left
            nt.left = copy(t.left)
            union_types(nt, nt.left)
            return nt

        if t.kind == "pair":
            nt = Type("pair")
            nt.left = copy(t.left)
            nt.right = copy(t.right)
            union_types(nt, nt.left)
            union_types(nt, nt.right)
            return nt

        if t.kind == "arrow":
            nt = Type("arrow")
            nt.left = copy(t.left)
            nt.right = copy(t.right)
            union_types(nt, nt.left)
            union_types(nt, nt.right)
            return nt

        raise TypeError(TypeError)

    return copy(t)


def build_builtin_schemes(ctx):
    schemes = {}

    schemes["int"] = ([], INT)
    schemes["bool"] = ([], BOOL)

    # fst : 'a * 'b -> 'a
    a = ctx.fresh(0)
    b = ctx.fresh(0)
    schemes["fst"] = ([a, b], make_arrow(make_pair(a, b), a))

    # snd : 'a * 'b -> 'b
    a = ctx.fresh(0)
    b = ctx.fresh(0)
    schemes["snd"] = ([a, b], make_arrow(make_pair(a, b), b))

    # hd : 'a list -> 'a
    a = ctx.fresh(0)
    schemes["hd"] = ([a], make_arrow(make_list(a), a))

    # tl : 'a list -> 'a list
    a = ctx.fresh(0)
    schemes["tl"] = ([a], make_arrow(make_list(a), make_list(a)))

    # null : 'a list -> bool
    a = ctx.fresh(0)
    schemes["null"] = ([a], make_arrow(make_list(a), BOOL))

    # +, -, * : int -> int -> int
    schemes["+"] = ([], make_arrow(INT, make_arrow(INT, INT)))
    schemes["-"] = ([], make_arrow(INT, make_arrow(INT, INT)))
    schemes["*"] = ([], make_arrow(INT, make_arrow(INT, INT)))

    # < : int -> int -> bool
    schemes["<"] = ([], make_arrow(INT, make_arrow(INT, BOOL)))

    # = : 'a -> 'a -> bool
    a = ctx.fresh(0)
    schemes["="] = ([a], make_arrow(a, make_arrow(a, BOOL)))

    # :: : 'a -> 'a list -> 'a list
    a = ctx.fresh(0)
    schemes["::"] = ([a], make_arrow(a, make_arrow(make_list(a), make_list(a))))

    return schemes


OPERATOR_NAMES = {
    "+": "+",
    "-": "-",
    "*": "*",
    "<": "<",
    "=": "=",
    "::": "::",
}


def infer_env(expr, env, ctx):
    kind = expr[0]

    if kind == "int":
        return INT
    if kind == "bool":
        return BOOL
    if kind == "nil":
        return make_list(ctx.fresh())
    if kind == "var":
        name = expr[1]
        if name not in env:
            raise NameError(NameError)
        return instantiate(env[name], ctx)

    if kind == "pair":
        return make_pair(infer_env(expr[1], env, ctx), infer_env(expr[2], env, ctx))

    if kind == "op2":
        op = expr[1]
        a = infer_env(expr[2], env, ctx)
        b = infer_env(expr[3], env, ctx)
        f = instantiate(env[op], ctx)
        r = ctx.fresh()
        unify(f, make_arrow(a, make_arrow(b, r)))
        return r

    if kind == "app":
        f = infer_env(expr[1], env, ctx)
        a = infer_env(expr[2], env, ctx)
        r = ctx.fresh()
        unify(f, make_arrow(a, r))
        return r

    if kind == "fun":
        args = expr[1]
        body = expr[2]
        old_level = ctx.level[0]
        ctx.level[0] = old_level + 1
        env2 = dict(env)
        arg_types = []
        for x in args:
            v = ctx.fresh(old_level)
            arg_types.append(v)
            env2[x] = ([], v)
        body_t = infer_env(body, env2, ctx)
        ctx.level[0] = old_level
        t = body_t
        for a in reversed(arg_types):
            t = make_arrow(a, t)
        return t

    if kind == "let":
        name = expr[1]
        expr1 = expr[2]
        body = expr[3]
        rec = expr[4]

        old_level = ctx.level[0]
        ctx.level[0] = old_level + 1

        if rec:
            fvar = ctx.fresh(ctx.level[0])
            env2 = dict(env)
            env2[name] = ([], fvar)
            t = infer_env(expr1, env2, ctx)
            unify(t, fvar)
            ctx.level[0] = old_level
            scheme = generalize(t, old_level)
        else:
            t = infer_env(expr1, env, ctx)
            ctx.level[0] = old_level
            scheme = generalize(t, old_level)

        env[name] = scheme
        ctx.level[0] = old_level + 1
        return infer_env(body, env, ctx)

    if kind == "if":
        cond = infer_env(expr[1], env, ctx)
        unify(cond, BOOL)
        t1 = infer_env(expr[2], env, ctx)
        t2 = infer_env(expr[3], env, ctx)
        unify(t1, t2)
        return t1

    raise TypeError(TypeError)


def type_var_name(i):
    base = ord("a") + (i % 26)
    suffix = i // 26
    if suffix == 0:
        return "'" + chr(base)
    return "'" + chr(base) + str(suffix)


def collect_vars(t):
    order = []
    seen = set()

    def visit(t):
        t = resolve(t)
        if t.kind == "var":
            if t.id not in seen:
                seen.add(t.id)
                order.append(t)
            return
        if t.kind == "list":
            visit(t.left)
        elif t.kind == "pair" or t.kind == "arrow":
            visit(t.left)
            visit(t.right)

    visit(t)
    return order


def needs_paren_for_list(t):
    t = resolve(t)
    return t.kind == "arrow" or t.kind == "pair"


def needs_paren_for_pair_side(t):
    t = resolve(t)
    return t.kind == "arrow" or t.kind == "pair"


def needs_paren_for_arrow_left(t):
    t = resolve(t)
    return t.kind == "arrow"


def print_type(t, var_names):
    t = resolve(t)
    k = t.kind
    if k == "int":
        return "int"
    if k == "bool":
        return "bool"
    if k == "var":
        return var_names[t.id]
    if k == "list":
        if needs_paren_for_list(t.left):
            return "(" + print_type(t.left, var_names) + ") list"
        return print_type(t.left, var_names) + " list"
    if k == "pair":
        left = print_type(t.left, var_names)
        right = print_type(t.right, var_names)
        if needs_paren_for_pair_side(t.left):
            left = "(" + left + ")"
        if needs_paren_for_pair_side(t.right):
            right = "(" + right + ")"
        return left + " * " + right
    if k == "arrow":
        left = print_type(t.left, var_names)
        right = print_type(t.right, var_names)
        if needs_paren_for_arrow_left(t.left):
            left = "(" + left + ")"
        return left + " -> " + right
    raise TypeError(TypeError)


def scheme_vars(t):
    vars_ = []
    seen = set()

    def visit(t):
        t = resolve(t)
        if t.kind == "var":
            if t.id not in seen:
                seen.add(t.id)
                vars_.append(t)
        elif t.kind == "list":
            visit(t.left)
        elif t.kind == "pair" or t.kind == "arrow":
            visit(t.left)
            visit(t.right)

    visit(t)
    return vars_


def infer(src: str) -> str:
    toks = Lexer(src).tokens()
    ast = Parser(toks).parse_all()

    ctx = InferContext()
    env = build_builtin_schemes(ctx)

    result = infer_env(ast, env, ctx)
    result = resolve(result)

    vars_ = collect_vars(result)
    var_names = {}
    for i, v in enumerate(vars_):
        var_names[v.id] = type_var_name(i)

    return print_type(result, var_names)
